 * Layer 1 — Hermes executor post-hoc recovery routine.
 *
 * Called from a try/finally around the hermes chat spawn in index.ts. Guarantees
 * that regardless of how Hermes exited (clean, signal, crash), the task has:
 *   - committed any uncommitted work
 *   - a PR on the feature branch (draft if no clean PR exists)
 *   - a handover.md describing what happened
 *   - a valid result.json at resultPath
 *
 * Idempotent: safe to call multiple times. No-op when the agent already wrote a
 * valid result.json with terminal_status "in_review".
 *
 * Non-throwing: every step is individually wrapped in try/catch. The finally block
 * always produces a result.json even if individual side-effects fail.
 */

import { execSync, spawnSync } from "node:child_process";
import {
  existsSync,
  readFileSync,
  writeFileSync,
  mkdirSync,
} from "node:fs";
import { join, dirname } from "node:path";
import type { ExecutorResult } from "@workflow/runtime-abi";
import { buildGitEnv } from "./git-env.js";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface SpawnResult {
  stdout: string;
  status: number | null;
  signal: string | null;
  error?: Error;
}

export interface RecoveryOpts {
  /** The result of the Hermes spawn, or undefined if the spawn itself failed. */
  spawnResult: SpawnResult | undefined;
  taskId: string;
  featureId: string;
  /** The impl repo feature branch (e.g. "feature/my-feature-T3"). */
  taskRepoBranch: string;
  /** Absolute path to the impl repo working directory. */
  taskRepoPath: string;
  /** SSH or HTTPS URL of the impl repo — used to derive GitHub coordinates. */
  taskRepoUrl: string;
  githubToken: string;
  sshKeyPath: string | undefined;
  gitAuthorEmail: string;
  gitAuthorName: string;
  /** Absolute path where result.json must be written. */
  resultPath: string;
  /**
   * The PR base branch for this task (e.g. "feature/my-feature"). When set,
   * draft PRs opened by recovery target this branch instead of the repo default.
   */
  taskBaseBranch?: string;
  tokenUsage?: { input: number; output: number };
}

// ── Internal helpers ──────────────────────────────────────────────────────────

function emitRecovery(event: Record<string, unknown>): void {
  console.log(JSON.stringify({ at: new Date().toISOString(), type: "recovery", ...event }));
}

function curlJson(args: string[]): unknown {
  const result = spawnSync("curl", args, {
    encoding: "utf-8",
    stdio: ["ignore", "pipe", "pipe"],
  });
  if (result.error) throw result.error;
  const stdout = result.stdout ?? "";
  if (!stdout.trim()) throw new Error(`curl returned empty response. stderr: ${result.stderr ?? ""}`);
  return JSON.parse(stdout);
}

/**
 * Parse GitHub owner/repo from an SSH or HTTPS remote URL.
 */
export function parseGitHubCoords(repoUrl: string): { owner: string; repo: string } {
  const sshMatch = /git@github\.com:([^/]+)\/([^.]+?)(?:\.git)?$/.exec(repoUrl);
  if (sshMatch) return { owner: sshMatch[1], repo: sshMatch[2] };
  const httpsMatch = /https?:\/\/github\.com\/([^/]+)\/([^/]+?)(?:\.git)?$/.exec(repoUrl);
  if (httpsMatch) return { owner: httpsMatch[1], repo: httpsMatch[2] };
  throw new Error(`Cannot parse GitHub coords from URL: "${repoUrl}"`);
}

/**
 * Classify the terminal reason from a spawn result.
 */
export function detectTerminalReason(spawnResult: SpawnResult | undefined): string {
  if (!spawnResult) return "executor_crashed";
  if (spawnResult.error) return "executor_spawn_error";
  if (spawnResult.signal) return `executor_signal_${spawnResult.signal}`;
  if (spawnResult.status !== 0) return "executor_crashed";
  return "result_not_written";
}

// ── PR helpers ─────────────────────────────────────────────────────────────────

interface PrListItem {
  html_url: string;
  number: number;
}

/**
 * Find an existing open PR on the branch, or open a new draft PR.
 * Returns the PR URL on success, or undefined if all attempts fail.
 */
function findOrOpenDraftPr(opts: {
  taskRepoUrl: string;
  taskRepoBranch: string;
  taskId: string;
  featureId: string;
  githubToken: string;
  lastCommitSha: string;
  taskBaseBranch?: string;
}): string | undefined {
  try {
    const { owner, repo } = parseGitHubCoords(opts.taskRepoUrl);
    const encodedHead = encodeURIComponent(`${owner}:${opts.taskRepoBranch}`);
    const listUrl =
      `https://api.github.com/repos/${owner}/${repo}/pulls` +
      `?head=${encodedHead}&state=open`;

    const prs = curlJson([
      "-s",
      "-H", `Authorization: token ${opts.githubToken}`,
      "-H", "Accept: application/vnd.github+json",
      listUrl,
    ]) as PrListItem[];

    if (Array.isArray(prs) && prs.length > 0) {
      return prs[0].html_url;
    }

    // No existing PR — open a draft.
    // Use the orchestrator-supplied taskBaseBranch (feature branch) when available;
    // fall back to the repo's default branch.
    let baseBranch = opts.taskBaseBranch ?? "main";
    if (!opts.taskBaseBranch) {
      try {
        const repoMeta = curlJson([
          "-s",
          "-H", `Authorization: token ${opts.githubToken}`,
          "-H", "Accept: application/vnd.github+json",
          `https://api.github.com/repos/${owner}/${repo}`,
        ]) as { default_branch?: string };
        if (repoMeta.default_branch) baseBranch = repoMeta.default_branch;
      } catch {
        /* fall through to "main" */
      }
    }

    const prTitle = `[WIP] feat(${opts.featureId}/${opts.taskId}): agent terminated — draft PR`;
    const prBody = [
      `## Task: ${opts.taskId}`,
      "",
      `**Branch:** \`${opts.taskRepoBranch}\``,
      `**Last commit:** ${opts.lastCommitSha}`,
      "",
      "Agent terminated before completion — see handover.md.",
      "",
      "_This draft PR was opened by the post-hoc recovery routine._",
    ].join("\n");

    const createUrl = `https://api.github.com/repos/${owner}/${repo}/pulls`;
    const requestBody = JSON.stringify({
      title: prTitle,
      body: prBody,
      head: opts.taskRepoBranch,
      base: baseBranch,
      draft: true,
    });

    const created = curlJson([
      "-s", "-X", "POST",
      "-H", `Authorization: token ${opts.githubToken}`,
      "-H", "Accept: application/vnd.github+json",
      "-H", "Content-Type: application/json",
      "-d", requestBody,
      createUrl,
    ]) as { html_url?: string; number?: number };

    if (!created.html_url) {
      emitRecovery({ step: "open_draft_pr", error: `GitHub response missing html_url: ${JSON.stringify(created)}` });
      return undefined;
    }
    return created.html_url;
  } catch (e) {
    emitRecovery({ step: "find_or_open_draft_pr", error: String(e) });
    return undefined;
  }
}

// ── Handover writer ────────────────────────────────────────────────────────────

function writeHandover(opts: {
  handoverPath: string;
  taskId: string;
  taskRepoBranch: string;
  lastCommitSha: string;
  lastCommitMessage: string;
  terminalReason: string;
  prUrl: string | undefined;
  taskRepoPath: string;
}): void {
  const filesChanged = (() => {
    try {
      return execSync(
        `git -C "${opts.taskRepoPath}" diff --name-status $(git -C "${opts.taskRepoPath}" merge-base HEAD origin/main 2>/dev/null || echo HEAD~1) HEAD`,
        { encoding: "utf-8", stdio: "pipe" },
      ).trim() || "(no changes detected)";
    } catch {
      return "(could not determine changed files)";
    }
  })();

  const lines = [
    `# Handover — ${opts.taskId}`,
    "",
    `**Terminal reason:** ${opts.terminalReason}`,
    `**Branch:** ${opts.taskRepoBranch}`,
    `**Last commit:** ${opts.lastCommitSha} ${opts.lastCommitMessage}`,
    `**PR:** ${opts.prUrl ?? "(none opened)"}`,
    "",
    "## Files modified in this run",
    "",
    "```",
    filesChanged,
    "```",
    "",
    "## Next agent — read this first",
    "",
    "This handover was written by the post-hoc recovery routine.",
    "The agent that produced these commits did not have a chance to",
    "write a structured handover. Re-claim the task, read the diff,",
    "continue where the last commit left off. If a checkpoint",
    "handover.md was written by the agent itself it will appear",
    "above this stub — read it first.",
  ];

  mkdirSync(dirname(opts.handoverPath), { recursive: true });
  writeFileSync(opts.handoverPath, lines.join("\n"), "utf-8");
}

// ── Public API ─────────────────────────────────────────────────────────────────

/**
 * Run the post-hoc recovery routine.
 *
 * No-op when the executor already wrote a valid result.json with terminal_status
 * "in_review". Otherwise: commits dirty work, pushes the branch, opens (or reuses)
 * a draft PR, writes handover.md, and writes terminal_status "blocked".
 *
 * Non-throwing — always produces result.json.
 */
export async function runRecovery(opts: RecoveryOpts): Promise<void> {
  const {
    spawnResult,
    taskId,
    featureId,
    taskRepoBranch,
    taskRepoPath,
    taskRepoUrl,
    githubToken,
    sshKeyPath,
    gitAuthorEmail,
    gitAuthorName,
    resultPath,
    tokenUsage,
    taskBaseBranch,
  } = opts;

  // ── 0. No-op when the executor already wrote a valid result ────────────────
  if (existsSync(resultPath)) {
    try {
      const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as Record<string, unknown>;
      if (raw && typeof raw === "object") {
        if (raw.terminal_status === "in_review" && raw.pr_url) return;
        // Skip recovery when a structured blocked result already exists — avoids
        // opening a draft PR for a clean branch (e.g. Phase 6 no_changes path).
        if (raw.terminal_status === "blocked" && raw.blocked_reason) return;
      }
    } catch { /* fall through to recovery */ }
  }

  emitRecovery({ step: "start", task_id: taskId, feature_id: featureId });

  // Preserve existing blocked_reason and blocked_suggestion if already set.
  let existingBlockedReason: string | undefined;
  let existingBlockedSuggestion: string | undefined;
  if (existsSync(resultPath)) {
    try {
      const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as Record<string, unknown>;
      if (typeof raw.blocked_reason === "string") existingBlockedReason = raw.blocked_reason;
      if (typeof raw.blocked_suggestion === "string") existingBlockedSuggestion = raw.blocked_suggestion;
    } catch { /* ignore */ }
  }

  const terminalReason = existingBlockedReason ?? detectTerminalReason(spawnResult);

  // ── 1. Commit dirty working tree ───────────────────────────────────────────
  let lastCommitSha = "";
  let lastCommitMessage = "";
  try {
    const porcelain = execSync(`git -C "${taskRepoPath}" status --porcelain`, {
      encoding: "utf-8",
      stdio: "pipe",
    }).trim();
    if (porcelain) {
      const gitEnv = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
      execSync(`git -C "${taskRepoPath}" add -A`, { env: gitEnv, stdio: "pipe" });
      execSync(
        `git -C "${taskRepoPath}" commit -m "wip(${taskId}): incomplete — agent terminated unexpectedly"`,
        { env: gitEnv, stdio: "pipe" },
      );
    }
    lastCommitSha = execSync(`git -C "${taskRepoPath}" rev-parse HEAD`, {
      encoding: "utf-8",
      stdio: "pipe",
    }).trim();
    lastCommitMessage = execSync(`git -C "${taskRepoPath}" log -1 --format=%s`, {
      encoding: "utf-8",
      stdio: "pipe",
    }).trim();
  } catch (e) {
    emitRecovery({ step: "commit_dirty_tree", error: String(e) });
  }

  // ── 2. Push branch (best-effort) ───────────────────────────────────────────
  try {
    execSync(`git -C "${taskRepoPath}" push origin "${taskRepoBranch}"`, {
      env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
      stdio: "pipe",
    });
  } catch (e) {
    emitRecovery({ step: "push_branch", error: String(e) });
  }

  // ── 3. Find or open draft PR ───────────────────────────────────────────────
  let prUrl: string | undefined;
  if (githubToken && taskRepoUrl) {
    prUrl = findOrOpenDraftPr({
      taskRepoUrl,
      taskRepoBranch,
      taskId,
      featureId,
      githubToken,
      lastCommitSha,
      taskBaseBranch,
    });
  }

  // ── 4. Write handover.md ───────────────────────────────────────────────────
  const handoverPath = join(dirname(resultPath), "handover.md");
  try {
    writeHandover({
      handoverPath,
      taskId,
      taskRepoBranch,
      lastCommitSha,
      lastCommitMessage,
      terminalReason,
      prUrl,
      taskRepoPath,
    });
  } catch (e) {
    emitRecovery({ step: "write_handover", error: String(e) });
  }

  // ── 5. Write result.json ───────────────────────────────────────────────────
  try {
    const result: ExecutorResult = {
      terminal_status: "blocked",
      blocked_reason: terminalReason,
      ...(existingBlockedSuggestion ? { blocked_suggestion: existingBlockedSuggestion } : {}),
      ...(tokenUsage ? { token_usage: tokenUsage } : {}),
      ...(prUrl ? { pr_url: prUrl } : {}),
      ...(existsSync(handoverPath) ? { handover_path: handoverPath } : {}),
    };
    mkdirSync(dirname(resultPath), { recursive: true });
    writeFileSync(resultPath, JSON.stringify(result), "utf-8");
    emitRecovery({ step: "wrote_result", terminal_status: "blocked", blocked_reason: terminalReason });
  } catch (e) {
    emitRecovery({ step: "write_result", error: String(e) });
  }
}

