describe("Phase 6 hermesDone short-circuit condition", () => {
  it("treats blocked+pr_url as hermesDone to prevent no_changes overwrite", () => {
    // When Hermes writes blocked:tests_failed with a pr_url, the hermesDone
    // predicate must be true so the wrapper never reaches commitAndPush and
    // overwrites the real blocked_reason with "no_changes".
    type PartialResult = { terminal_status: string; pr_url?: string; blocked_reason?: string };

