      { result: { terminal_status: "in_review", pr_url: "https://github.com/a/b/pull/1" }, expected: true },
      { result: { terminal_status: "blocked", pr_url: "https://github.com/a/b/pull/1", blocked_reason: "tests_failed" }, expected: true },
      { result: { terminal_status: "blocked", pr_url: "", blocked_reason: "no_changes" }, expected: false },
      { result: { terminal_status: "blocked" }, expected: false },
      { result: { terminal_status: "failed", pr_url: "https://github.com/a/b/pull/1" }, expected: false },
