# Fetch all unresolved review threads via GraphQL to find any matching threads.
curl -s -X POST \
  -H "Authorization: Bearer $GITHUB_TOKEN" \
  -H "Content-Type: application/json" \
  "https://api.github.com/graphql" \
  -d '{
    "query": "query($owner:String!,$name:String!,$number:Int!){repository(owner:$owner,name:$name){pullRequest(number:$number){reviewThreads(first:100){nodes{id isResolved comments(first:10){nodes{databaseId path line body author{login}}}}}}}}",
    "variables": {"owner": "tiendv89", "name": "agent-workflow", "number": 225}
  }' | jq '.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved == false) | {id, isResolved, comments: .comments.nodes}'

